describe('Long-Running Task Persistence Across Page Refreshes', () => {
  beforeEach(() => {
    cy.visit('/tasks');
  });

  it('should persist long-running task state across page refresh', () => {
    // Start a long-running task
    cy.get('[data-testid="start-task-button"]').click();
    cy.intercept('POST', '/api/tasks/start').as('startTask');
    cy.wait('@startTask');

    // Verify task is initiated and in progress
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.get('[data-testid="task-progress-bar"]').should('be.visible');

    // Simulate page refresh
    cy.reload();

    // Verify task state is still persisted after refresh
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');
    cy.get('[data-testid="task-progress-bar"]').should('be.visible');
    cy.get('[data-testid="task-progress-bar"]').should('have.attr', 'style', 'width: 50%');

    // Verify task details are still visible
    cy.get('[data-testid="task-name"]').should('contain', 'Data Processing');
    cy.get('[data-testid="task-id"]').should('be.visible');

    // Verify task can be interacted with
    cy.get('[data-testid="cancel-task-button"]').should('be.visible');
    cy.get('[data-testid="cancel-task-button"]').click();
    cy.intercept('POST', '/api/tasks/cancel').as('cancelTask');
    cy.wait('@cancelTask');

    // Verify task is cancelled
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="task-progress-bar"]').should('not.exist');
  });

  it('should handle task cancellation and persistence across page refresh', () => {
    // Start a long-running task
    cy.get('[data-testid="start-task-button"]').click();
    cy.intercept('POST', '/api/tasks/start').as('startTask');
    cy.wait('@startTask');

    // Verify task is in progress
    cy.get('[data-testid="task-status"]').should('contain', 'In Progress');

    // Cancel the task
    cy.get('[data-testid="cancel-task-button"]').click();
    cy.intercept('POST', '/api/tasks/cancel').as('cancelTask');
    cy.wait('@cancelTask');

    // Verify task is cancelled
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="task-progress-bar"]').should('not.exist');

    // Refresh the page
    cy.reload();

    // Verify task state is persisted as cancelled
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
    cy.get('[data-testid="task-name"]').should('contain', 'Data Processing');

    // Verify task cannot be restarted if already cancelled
    cy.get('[data-testid="start-task-button"]').should('be.disabled');
    cy.get('[data-testid="task-status"]').should('contain', 'Cancelled');
  });
});
